import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office - quote premiums", () => {
  // Edge case: empty item list
  it.todo("empty item list -> premium 5 G (only processing fee)");

  // Base item premiums (single item, newcomer 0 years, first insurance surcharge applies)
  // For isolating base premiums we use a long-standing... actually base premium is item base.
  // We test base premium + fee only via a plain item where no first-insurance? First insurance always applies to each item.
  // Simplest: single plain sword. base 100 + first insurance 10 = 110 + 5 fee = 115
  it.todo("single plain sword (newcomer) -> premium 115 G (100 base + 10 first + 5 fee)");
  it.todo("single plain amulet (newcomer) -> premium 71 G (60 base + 6 first + 5 fee)");
  it.todo("single plain staff (newcomer) -> premium 93 G (80 base + 8 first + 5 fee)");
  it.todo("single plain potion (newcomer) -> premium 49 G (40 base + 4 first + 5 fee)");

  // Components
  it.todo("2 runes -> base premium 50 G (25 each)");
  it.todo("3 runes -> base premium 60 G (block applies)");
  it.todo("4 runes -> base premium 100 G (no block; block requires exactly 3)");
  it.todo("7 runes -> base premium 175 G");

  // "Alike" components
  it.todo("2 runes + 1 moonstone -> base premium 75 G (no block: different types)");
  it.todo("3 runes + 3 moonstones -> base premium 120 G (two separate blocks)");

  // Modifier scope on multi-item policies
  it.todo("cursed sword + plain amulet -> 210 G before fee (base 160 + 50 curse on sword)");

  // Modifier thresholds
  it.todo("customer with exactly 2 years -> loyalty discount applies");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies");
  it.todo("sword with enchantment 5 and cursed -> both surcharges apply");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");

  // Rounding for premium
  it.todo("premium calculation yielding 197.5 G -> final premium 198 G (rounded up)");

  // Integration: newcomer with cursed sword -> 165 G
  it.todo("newcomer with cursed sword (steel, ench 3) -> premium 165 G");

  // Integration: long-standing customer's second contract -> 160 G
  it.todo("long-standing (3y) second contract, cursed sword ench 7 -> premium 160 G");
});

describe("Claim Office - claim payouts", () => {
  // Standard reimbursement
  it.todo("regular sword (steel, ench 3), damage 500 G -> payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G -> payout 100 G");

  // Enchantment threshold vs dragon material
  it.todo("dragon sword ench 8, damage 1000 G -> payout 400 G (50% then deductible)");
  it.todo("dragon sword ench 9, damage 1000 G -> payout 400 G (50% wins then deductible)");
  it.todo("dragon sword ench 5, damage 800 G -> payout 700 G (full then deductible)");
  it.todo("steel sword ench 9, damage 1000 G -> payout 400 G (50% then deductible)");

  // Deductible per damage event
  it.todo("dragon attack: sword 500 + amulet 300 -> payout 600 G (deductible per item)");

  // Rounding for payout
  it.todo("payout calculation yielding 350.5 G -> final payout 350 G (rounded down)");

  // Cap exhaustion
  it.todo("cursed sword cap based on unmodified value -> cap 2000 G");
  it.todo("policy sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("policy sword + 3 runes block -> insurance sum 1750 G");
  it.todo("two successive claims 1500 each: first payout 1400 remaining 600, second payout 600 remaining 0");

  // Multiple items of same type
  it.todo("two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damages each get own deductible");
  it.todo("more sword damages than swords insured -> non-zero exit / rejected");
});

describe("Claim Office - error handling", () => {
  it.todo("quote with unknown item type -> non-zero exit, error to stderr, no results");
  it.todo("claim referencing item not in policy -> non-zero exit, error to stderr");
  it.todo("claim with negative damage amount -> non-zero exit, error to stderr");
});

