export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
}

export interface ScenarioResult {
  results: unknown[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

const FIRST_INSURANCE_SURCHARGE = 0.1;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map((step) => {
    const itemsTotal = step.items.reduce((sum, item) => {
      const base = BASE_PREMIUMS[item.type];
      return sum + base + base * FIRST_INSURANCE_SURCHARGE;
    }, 0);
    return { premium: itemsTotal + PROCESSING_FEE };
  });
  return { results };
};

