const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const componentsBasePremium = (count: number): number => {
  const blocks = Math.floor(count / COMPONENT_BLOCK_SIZE);
  const remainder = count % COMPONENT_BLOCK_SIZE;
  return blocks * COMPONENT_BLOCK_PREMIUM + remainder * BASE_PREMIUMS.rune;
};

const itemsBasePremium = (items: Item[]): number => {
  const runes = items.filter((item) => item.type === "rune");
  const others = items.filter((item) => item.type !== "rune");
  const othersBase = others.reduce((sum, item) => sum + itemBasePremium(item), 0);
  return othersBase + componentsBasePremium(runes.length);
};

const quotePremium = (step: QuoteStep): number => {
  const base = itemsBasePremium(step.items);
  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
  return base + firstInsuranceSurcharge + PROCESSING_FEE;
};

