const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const isComponent = (item: Item): boolean =>
  COMPONENT_TYPES.includes(item.type);

const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const componentTypeBasePremium = (count: number): number => {
  if (count === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_PREMIUM;
  }
  return count * COMPONENT_BASE_PREMIUM;
};

const componentsBasePremium = (components: Item[]): number => {
  const countsByType = new Map<string, number>();
  for (const component of components) {
    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
  }
  let total = 0;
  for (const count of countsByType.values()) {
    total += componentTypeBasePremium(count);
  }
  return total;
};

const itemsBasePremium = (items: Item[]): number => {
  const components = items.filter(isComponent);
  const nonComponents = items.filter((item) => !isComponent(item));
  const nonComponentsBase = nonComponents.reduce(
    (sum, item) => sum + itemBasePremium(item),
    0,
  );
  return nonComponentsBase + componentsBasePremium(components);
};

