const policySurcharges = (base: number, customer: Customer): number => {
  const firstInsurance = base * FIRST_INSURANCE_SURCHARGE_RATE;
  const loyalty =
    customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS
      ? base * LOYALTY_DISCOUNT_RATE
      : 0;
  return firstInsurance - loyalty;
};

const quotePremium = (step: QuoteStep, customer: Customer): number => {
