    base +
    itemSurcharges(step.items) +
    policySurcharges(base, customer) +
    PROCESSING_FEE
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step, scenario.customer),
  }));
  return { results };
};

