    const base = itemBasePremium(item);
    if (item.cursed) {
      total += base * CURSE_SURCHARGE_RATE;
    }
    if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_MIN_LEVEL) {
      total += base * HIGH_ENCHANTMENT_SURCHARGE_RATE;
    }
  }
  return total;
};

