// Premiums round up, in MHPCO's favor.
const roundPremiumUp = (amount: number): number => Math.ceil(amount);

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const processClaim = (step: ClaimStep, quotes: QuoteStep[]): ClaimResult => {
  const policy = quotes[step.policy];
  const cap = insuranceSum(policy.items) * CAP_MULTIPLIER;
  const payout = step.incident.damages.reduce(
    (sum, damage) => sum + damagePayout(damage),
    0,
  );
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quotes: QuoteStep[] = [];
  const results: StepResult[] = scenario.steps.map((step) => {
    if (step.op === "claim") {
      return processClaim(step, quotes);
    }
    quotes.push(step);
    const quoteNumber = quotes.length;
    return {
      premium: roundPremiumUp(
        quotePremium(step, scenario.customer, quoteNumber),
      ),
    };
  });
  return { results };
};

