const processClaim = (
  step: ClaimStep,
  quotesByStepIndex: Map<number, QuoteStep>,
): ClaimResult => {
  const policy = quotesByStepIndex.get(step.policy)!;
  const cap = insuranceSum(policy.items) * CAP_MULTIPLIER;
  const payout = step.incident.damages.reduce(
    (sum, damage) => sum + damagePayout(damage),
    0,
  );
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quotesByStepIndex = new Map<number, QuoteStep>();
  let quoteNumber = 0;
  const results: StepResult[] = scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      return processClaim(step, quotesByStepIndex);
    }
    quotesByStepIndex.set(index, step);
    quoteNumber += 1;
    return {
      premium: roundPremiumUp(
        quotePremium(step, scenario.customer, quoteNumber),
      ),
    };
  });
  return { results };
};

